import { useEffect, useState } from 'react';
import { GameEngine } from '../game/gameEngine';
import { PatternDisplay } from './PatternDisplay';
import { GameSession, PlayerState } from '../types';

interface GameBoardProps {
  jevApiKey?: string;
  mode: 'local' | 'online';
  playerName?: string;
  onGameOver: (score: number, player: PlayerState) => void;
  onBack: () => void;
}

export const GameBoard = ({ jevApiKey, mode, playerName, onGameOver, onBack }: GameBoardProps) => {
  const [gameEngine] = useState(() => new GameEngine(jevApiKey));
  const [session, setSession] = useState<GameSession | null>(null);
  const [timeRemaining, setTimeRemaining] = useState(0);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [multiplayerGameState, setMultiplayerGameState] = useState<any>(null);
  const [currentGameId, setCurrentGameId] = useState<string | null>(null);

  useEffect(() => {
    startGame();

    // Setup multiplayer event handlers if in online mode
    if (mode === 'online' && playerName) {
      gameEngine.setupMultiplayerEventHandlers({
        onGameStarted: (gameState) => {
          setMultiplayerGameState(gameState);
          setSession({
            id: gameState.gameId,
            mode: 'online',
            players: gameState.players,
            currentPattern: gameState.currentPattern,
            status: 'active',
            startTime: Date.now()
          });
          setTimeRemaining(gameState.timeLimit);
          setMessage('Multiplayer game started!');
          setLoading(false);
        },
        onPlayerJoined: (data) => {
          setMessage(`${data.player.name} joined the game!`);
          if (session) {
            setSession({
              ...session,
              players: data.game.players
            });
          }
        },
        onPlayerLeft: () => {
          setMessage('A player left the game');
        },
        onAnswerResult: (data) => {
          setMessage(`Player ${data.playerId} answered: ${data.result.isCorrect ? 'Correct!' : 'Wrong!'}`);
          if (data.result.nextPattern) {
            setSession(prev => prev ? { ...prev, currentPattern: data.result.nextPattern } : null);
            setTimeRemaining(data.result.nextPattern.timeLimit);
          }
          if (data.result.roundEnded) {
            handleMultiplayerRoundEnd(data.result);
          }
        },
        onGameEnded: (results) => {
          const player = results.finalRankings.find((r: any) => r.playerId === gameEngine.getCurrentSession()?.players[0].id);
          if (player) {
            onGameOver(player.score, {
              id: player.playerId,
              score: player.score,
              level: player.level,
              patternsSolved: player.patternsSolved,
              patternsFailed: player.patternsFailed,
              strengths: { numeric: 0.5, visual: 0.5, logical: 0.5, sequence: 0.5, geometric: 0.5 },
              weaknesses: { numeric: 0.5, visual: 0.5, logical: 0.5, sequence: 0.5, geometric: 0.5 },
              averageTime: player.avgTime,
              streak: player.streak
            });
          }
          gameEngine.disconnect();
        }
      });
    }

    return () => {
      if (mode === 'online') {
        gameEngine.disconnect();
      }
    };
  }, [mode, playerName]);

  const startGame = async () => {
    setLoading(true);
    try {
      if (mode === 'local') {
        const newSession = await gameEngine.startLocalGame('player-1');
        setSession(newSession);
        setTimeRemaining(newSession.currentPattern?.timeLimit || 10);
        setMessage('Game started! Solve the pattern:');

        // Track analytics
        gameEngine.trackAnalyticsEvent('game_started', {
          mode: 'local',
          timestamp: Date.now()
        });
      } else if (playerName) {
        // For online mode, we'll wait for the user to join/create a game via lobby
        const newSession = await gameEngine.startOnlineGame('player-1', playerName);
        setSession(newSession);
        setMessage('Connected to server! Join or create a game.');

        // Track analytics
        gameEngine.trackAnalyticsEvent('online_mode_entered', {
          playerName,
          timestamp: Date.now()
        });
      }
      setLoading(false);
    } catch (error) {
      setMessage('Failed to start game. Please try again.');
      setLoading(false);
    }
  };

  const handleAnswer = async (answer: any) => {
    if (!session) return;

    const timeTaken = 1.0; // Simplified timing for MVP

    try {
      if (mode === 'local') {
        const result = await gameEngine.submitAnswer('player-1', answer, timeTaken);
        setMessage(result.message);

        // Track analytics
        gameEngine.trackAnalyticsEvent('answer_submitted', {
          isCorrect: result.correct,
          timeTaken,
          patternType: session.currentPattern?.type
        });

        if (result.nextPattern) {
          setTimeRemaining(result.nextPattern.timeLimit);
        } else {
          // Game over
          const player = session.players[0];
          onGameOver(player.score, player);

          // Track analytics
          gameEngine.trackAnalyticsEvent('game_completed', {
            finalScore: player.score,
            patternsSolved: player.patternsSolved,
            duration: Date.now() - session.startTime
          });
        }
      } else if (currentGameId) {
        const result = await gameEngine.submitMultiplayerAnswer(currentGameId, answer, timeTaken);
        setMessage(result.message);

        // Track analytics
        gameEngine.trackAnalyticsEvent('multiplayer_answer_submitted', {
          gameId: currentGameId,
          isCorrect: result.isCorrect,
          timeTaken
        });
      }
    } catch (error) {
      setMessage('Error submitting answer. Please try again.');
    }
  };

  const handleMultiplayerRoundEnd = (result: any) => {
    if (result.currentRound >= result.maxRounds) {
      setMessage('Game ending...');
    } else {
      setMessage(`Round ${result.currentRound - 1} complete! Get ready for round ${result.currentRound}`);
    }
  };

  const handleHint = async () => {
    if (!session) return;
    const hint = await gameEngine.getHint();
    if (session.currentPattern) {
      setSession({
        ...session,
        currentPattern: { ...session.currentPattern, hint }
      });

      // Track analytics
      gameEngine.trackAnalyticsEvent('hint_used', {
        patternType: session.currentPattern.type
      });
    }
  };

  const handleJoinGame = (gameId: string) => {
    setCurrentGameId(gameId);
  };

  if (loading) {
    return (
      <div className="game-board loading">
        <div className="spinner">Loading game...</div>
      </div>
    );
  }

  if (mode === 'online' && !currentGameId && session?.status === 'waiting') {
    // Show multiplayer lobby
    const { MultiplayerLobby } = require('./MultiplayerLobby');
    return (
      <MultiplayerLobby
        gameEngine={gameEngine}
        playerName={playerName || 'Player'}
        onGameJoined={handleJoinGame}
        onBack={onBack}
      />
    );
  }

  if (!session || !session.currentPattern) {
    return (
      <div className="game-board error">
        <button onClick={onBack} className="back-btn">← Back</button>
        <div className="error-message">{message}</div>
        <button onClick={startGame} className="retry-btn">Try Again</button>
      </div>
    );
  }

  const player = session.players[0];

  return (
    <div className="game-board">
      <div className="game-header">
        <button onClick={onBack} className="back-btn">← Back</button>
        <div className="player-info">
          <span className="score">Score: {player.score}</span>
          <span className="level">Level: {player.level}</span>
          <span className="streak">Streak: {player.streak}🔥</span>
        </div>
        <div className="game-mode">{mode.toUpperCase()} MODE</div>
      </div>

      {mode === 'online' && multiplayerGameState && (
        <div className="multiplayer-status">
          <span className="round-info">Round {multiplayerGameState.currentRound}/{multiplayerGameState.maxRounds}</span>
          <span className="players-count">{session.players.length} players</span>
        </div>
      )}

      <div className="message-bar">{message}</div>

      {session.currentPattern && (
        <PatternDisplay
          pattern={session.currentPattern}
          onAnswer={handleAnswer}
          onHint={handleHint}
          timeRemaining={timeRemaining}
        />
      )}

      <div className="game-stats">
        <div className="stat">
          <span className="stat-label">Solved:</span>
          <span className="stat-value">{player.patternsSolved}</span>
        </div>
        <div className="stat">
          <span className="stat-label">Failed:</span>
          <span className="stat-value">{player.patternsFailed}</span>
        </div>
        <div className="stat">
          <span className="stat-label">Avg Time:</span>
          <span className="stat-value">{player.averageTime.toFixed(1)}s</span>
        </div>
      </div>
    </div>
  );
};
